CREATE TABLE knowledge_document(id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,category VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,file_name VARCHAR(255) NOT NULL,media_type VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,storage_key VARCHAR(512) NOT NULL,status VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,visibility VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'INTERNAL',uploaded_by BIGINT NOT NULL,reviewed_by BIGINT NULL,review_comment VARCHAR(500) NULL,published_at DATETIME(6) NULL,expires_at DATETIME(6) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_knowledge_status_category(status,category),INDEX idx_knowledge_sha(sha256));
CREATE TABLE knowledge_chunk(id BIGINT NOT NULL,document_id BIGINT NOT NULL,chunk_index INT UNSIGNED NOT NULL,heading VARCHAR(500) NULL,content MEDIUMTEXT NOT NULL,token_count INT UNSIGNED NOT NULL,content_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ACTIVE',PRIMARY KEY(id),UNIQUE KEY uk_knowledge_chunk_index(document_id,chunk_index),CONSTRAINT fk_knowledge_chunk_document FOREIGN KEY(document_id) REFERENCES knowledge_document(id) ON DELETE CASCADE);
CREATE TABLE knowledge_review(id BIGINT NOT NULL,document_id BIGINT NOT NULL,reviewer_id BIGINT NOT NULL,decision VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,comment VARCHAR(500) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_knowledge_review_document(document_id,created_at));
CREATE TABLE knowledge_index_job(id BIGINT NOT NULL,document_id BIGINT NOT NULL,index_version VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,job_type VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,retry_count INT UNSIGNED NOT NULL DEFAULT 0,next_retry_at DATETIME(6) NULL,last_error VARCHAR(1000) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_knowledge_index_dispatch(status,next_retry_at));
